questionvariables.text:
Srx: matrix([1,0],[0,-1]); Sry: matrix([-1,0],[0,1]); Sryx: matrix([0,1],[1,0]); Srmyx: matrix([0,-1],[-1,0]);
Sr90: matrix([0,-1],[1,0]); Sr180: matrix([-1,0],[0,-1]); Sr270: matrix([0,1],[-1,0]);
symkeys: ["rx","ry","ryx","rmyx","r90","r180","r270"];
symmats: [Srx,Sry,Sryx,Srmyx,Sr90,Sr180,Sr270];
sm(k) := symmats[sublist_indices(symkeys, lambda([u], u=k))[1]];
sn(k) := sublist_indices(symkeys, lambda([u], u=k))[1];
skey(A) := block([j], j: sublist_indices(symmats, lambda([u], is(u=A))), if j=[] then "none" else symkeys[j[1]]);
/* Design: classify-the-objects pattern. Source: original. One row is an enlargement (position epos); its correct option, scale factor 1/k, is third of four, never first. Isometry rows: the first option ("it has no inverse") is never correct. */
ilist: [[["ry","rx","r270"],1/3,3],[["ryx","r90","r270"],1/2,1],[["ry","r270","rmyx"],4,4],[["rx","ry","r180"],5/2,2],[["r90","rmyx","rx"],3,1],[["r90","r180","ry"],2,1],[["rmyx","ry","r270"],-2,3],[["ry","rx","r90"],-1/2,3],[["rx","ryx","r270"],-3,1],[["rx","rmyx","ry"],-4,1]];
ix: 1+rand(10);
iso: ilist[ix][1]; kk: ilist[ix][2]; epos: ilist[ix][3];
/* inverse and named error, index-matched to symkeys */
invk: ["rx","ry","ryx","rmyx","r270","r180","r90"];
errk: ["ry","rx","rmyx","ryx","r90","r90","r270"];
rowkey(r) := if r=epos then "enl" else iso[if r<epos then r else r-1];
ms(v) := ssubst("−","-",string(v));
etx(v) := sconcat("enlargement, centre O, scale factor ", ms(v));
R1: rowkey(1);
opt1: [["noinv1", false, "it has no inverse"], ["rx1", if R1="enl" then false else is(invk[sn(R1)]="rx"), "reflection in the x-axis"], ["ry1", if R1="enl" then false else is(invk[sn(R1)]="ry"), "reflection in the y-axis"], ["ryx1", if R1="enl" then false else is(invk[sn(R1)]="ryx"), "reflection in the line y = x"], ["rmyx1", if R1="enl" then false else is(invk[sn(R1)]="rmyx"), "reflection in the line y = −x"], ["r901", if R1="enl" then false else is(invk[sn(R1)]="r90"), "rotation of 90° anticlockwise about O"], ["r1801", if R1="enl" then false else is(invk[sn(R1)]="r180"), "rotation of 180° about O"], ["r2701", if R1="enl" then false else is(invk[sn(R1)]="r270"), "rotation of 90° clockwise about O"], ["ek1",false,etx(kk)],["emk1",false,etx(-kk)],["erk1",is(R1="enl"),etx(1/kk)],["emrk1",false,etx(-1/kk)]];
ta1: first(mcq_correct(opt1));
dg1: if R1="enl" then opt1[10][1] else opt1[1+sn(errk[sn(R1)])][1];
gw1: if R1="enl" then opt1[9][1] else opt1[1][1];
E1: if R1="enl" then "none" else errk[sn(R1)];
I1: if R1="enl" then "none" else invk[sn(R1)];
R2: rowkey(2);
opt2: [["noinv2", false, "it has no inverse"], ["rx2", if R2="enl" then false else is(invk[sn(R2)]="rx"), "reflection in the x-axis"], ["ry2", if R2="enl" then false else is(invk[sn(R2)]="ry"), "reflection in the y-axis"], ["ryx2", if R2="enl" then false else is(invk[sn(R2)]="ryx"), "reflection in the line y = x"], ["rmyx2", if R2="enl" then false else is(invk[sn(R2)]="rmyx"), "reflection in the line y = −x"], ["r902", if R2="enl" then false else is(invk[sn(R2)]="r90"), "rotation of 90° anticlockwise about O"], ["r1802", if R2="enl" then false else is(invk[sn(R2)]="r180"), "rotation of 180° about O"], ["r2702", if R2="enl" then false else is(invk[sn(R2)]="r270"), "rotation of 90° clockwise about O"], ["ek2",false,etx(kk)],["emk2",false,etx(-kk)],["erk2",is(R2="enl"),etx(1/kk)],["emrk2",false,etx(-1/kk)]];
ta2: first(mcq_correct(opt2));
dg2: if R2="enl" then opt2[10][1] else opt2[1+sn(errk[sn(R2)])][1];
gw2: if R2="enl" then opt2[9][1] else opt2[1][1];
E2: if R2="enl" then "none" else errk[sn(R2)];
I2: if R2="enl" then "none" else invk[sn(R2)];
R3: rowkey(3);
opt3: [["noinv3", false, "it has no inverse"], ["rx3", if R3="enl" then false else is(invk[sn(R3)]="rx"), "reflection in the x-axis"], ["ry3", if R3="enl" then false else is(invk[sn(R3)]="ry"), "reflection in the y-axis"], ["ryx3", if R3="enl" then false else is(invk[sn(R3)]="ryx"), "reflection in the line y = x"], ["rmyx3", if R3="enl" then false else is(invk[sn(R3)]="rmyx"), "reflection in the line y = −x"], ["r903", if R3="enl" then false else is(invk[sn(R3)]="r90"), "rotation of 90° anticlockwise about O"], ["r1803", if R3="enl" then false else is(invk[sn(R3)]="r180"), "rotation of 180° about O"], ["r2703", if R3="enl" then false else is(invk[sn(R3)]="r270"), "rotation of 90° clockwise about O"], ["ek3",false,etx(kk)],["emk3",false,etx(-kk)],["erk3",is(R3="enl"),etx(1/kk)],["emrk3",false,etx(-1/kk)]];
ta3: first(mcq_correct(opt3));
dg3: if R3="enl" then opt3[10][1] else opt3[1+sn(errk[sn(R3)])][1];
gw3: if R3="enl" then opt3[9][1] else opt3[1][1];
E3: if R3="enl" then "none" else errk[sn(R3)];
I3: if R3="enl" then "none" else invk[sn(R3)];
R4: rowkey(4);
opt4: [["noinv4", false, "it has no inverse"], ["rx4", if R4="enl" then false else is(invk[sn(R4)]="rx"), "reflection in the x-axis"], ["ry4", if R4="enl" then false else is(invk[sn(R4)]="ry"), "reflection in the y-axis"], ["ryx4", if R4="enl" then false else is(invk[sn(R4)]="ryx"), "reflection in the line y = x"], ["rmyx4", if R4="enl" then false else is(invk[sn(R4)]="rmyx"), "reflection in the line y = −x"], ["r904", if R4="enl" then false else is(invk[sn(R4)]="r90"), "rotation of 90° anticlockwise about O"], ["r1804", if R4="enl" then false else is(invk[sn(R4)]="r180"), "rotation of 180° about O"], ["r2704", if R4="enl" then false else is(invk[sn(R4)]="r270"), "rotation of 90° clockwise about O"], ["ek4",false,etx(kk)],["emk4",false,etx(-kk)],["erk4",is(R4="enl"),etx(1/kk)],["emrk4",false,etx(-1/kk)]];
ta4: first(mcq_correct(opt4));
dg4: if R4="enl" then opt4[10][1] else opt4[1+sn(errk[sn(R4)])][1];
gw4: if R4="enl" then opt4[9][1] else opt4[1][1];
E4: if R4="enl" then "none" else errk[sn(R4)];
I4: if R4="enl" then "none" else invk[sn(R4)];
